const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

assert.equal(satisfies('0.2.5', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.9', '^1.2.0'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// Backtracking must undo the failed choice's constraints (previously leaked).
const bt = {
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
};
assert.deepEqual(resolve(bt, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// Cycles terminate and do not hit an iteration cap.
const cyc = { x: { '1.0.0': { y: '^1.0.0' } }, y: { '1.0.0': { x: '^1.0.0', y: '*' } } };
assert.deepEqual(resolve(cyc, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// Long chain without recursion.
const chain = {};
const n = 20000;
for (let i = 0; i < n; i += 1) chain[`p${i}`] = { '1.0.0': i + 1 < n ? { [`p${i + 1}`]: '1.0.0' } : {} };
